  "steps": [
    {
      "id": 1,
      "claim": "CT scans involve significant out-of-pocket costs for uninsured patients, ranging from hundreds to thousands of dollars.",
      "evidence": "US healthcare pricing data indicates CT scan charges typically range from $300 to over $3,000 depending on the facility and complexity.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Insured patients typically face significantly lower out-of-pocket costs (copays/deductibles) for CT scans compared to the full list price.",
      "evidence": "Standard health insurance plans cover diagnostic imaging, reducing patient liability to a fraction of the total charge (often <$150).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The financial barrier to obtaining a CT scan is substantially higher for uninsured individuals than for insured individuals.",
      "evidence": "Comparing the cost structures: Uninsured pays 100% of the charge; Insured pays a small percentage or fixed copay. The delta in financial burden is large.",
      "weight": 0.15,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "High out-of-pocket costs are a primary determinant of healthcare utilization, causing patients to decline non-emergency procedures.",
      "evidence": "Health economics literature and empirical studies (e.g., JAMA) show that lack of insurance and high cost-sharing lead to lower rates of elective imaging and diagnostic testing.",
      "weight": 0.2,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Devil's Advocate Check: Even if an uninsured person has high clinical need, the financial constraint remains the dominant variable in the decision to *decline* the procedure.",
      "evidence": "While clinical urgency can override cost, the question asks about likelihood of declining. Empirical data shows that even when clinically indicated, uninsured patients are statistically more likely to refuse or delay care due to cost compared to insured peers.",
      "weight": 0.2,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Therefore, an uninsured person is more likely to decline a CT scan than an insured person.",
      "evidence": "Synthesizing the higher financial barrier (Step 3) with the established price sensitivity of healthcare demand (Step 4) leads to the conclusion that the uninsured group has a higher probability of refusal.",
      "weight": 0.15,
      "depends_on": [5]
    }
  ],
